<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';

use App\Repositories\{AdminRepository,InterviewRepository};
use App\Services\{AdminOperationsService,AuditService,AvailabilityService,BookingService,BusinessHoursService,ResourceAssignmentService};
use App\Support\{Config,Database,FrozenClock};
use App\Validation\ValidationException;

if(Config::get('APP_ENV')!=='testing'||!str_contains(strtolower(Config::get('DB_DATABASE')),'test'))throw new RuntimeException('Phase 3 tests require a disposable testing database.');
$db=Database::connection();$checks=0;
function p3ok(bool $value,string $message):void{global $checks;if(!$value){fwrite(STDERR,'FAIL: '.$message.PHP_EOL);throw new RuntimeException('FAIL: '.$message);}$checks++;}
function p3reject(callable $fn,string $text):void{try{$fn();}catch(ValidationException $e){p3ok(str_contains(implode(' ',$e->errors),$text),'Expected rejection: '.$text);return;}throw new RuntimeException('FAIL: Expected rejection: '.$text);}
function p3input(int $technology,string $date,string $time,string $type='NORMAL',?int $support=null,int $duration=30):array{return ['company_name'=>'Phase Three Co','job_role'=>'Engineer','technology_id'=>(string)$technology,'interview_round'=>'Round 2','hr_availability'=>'available','hr_name'=>'Recruiter','hr_phone'=>'+919876543210','interview_type'=>$type,'support_person_id'=>$support?(string)$support:'','duration'=>(string)$duration,'date'=>$date,'time'=>$time];}
function p3candidate(PDO $db,int $technology,string $name,string $phone,string $classification='Genuine'):int{$q=$db->prepare("INSERT INTO users(role,full_name,phone,password_hash) VALUES('CANDIDATE',?,?,?)");$q->execute([$name,$phone,password_hash('TestingPassword12',PASSWORD_DEFAULT)]);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO candidate_profiles(user_id,technology_id,classification) VALUES(?,?,?)');$q->execute([$id,$technology,$classification]);return $id;}
function p3services(PDO $db,string $now):array{$clock=new FrozenClock(new DateTimeImmutable($now));$hours=new BusinessHoursService($db,$clock);$availability=new AvailabilityService($db,$hours,new ResourceAssignmentService($db));return [$hours,new BookingService($db,$availability,$hours,new AuditService($db))];}
function p3hours(array $overrides=[]):array{$data=['advance_minutes'=>'90','cutoff_minutes'=>'75','open'=>[],'opens'=>[],'closes'=>[]];for($d=1;$d<=7;$d++){$data['opens'][$d]='10:00';$data['closes'][$d]='19:00';if($d<7)$data['open'][$d]='1';}return array_replace_recursive($data,$overrides);}

$db->exec("INSERT INTO technologies(name,active) VALUES('Phase3 Java',1),('Phase3 Python',1)");$tech=(int)$db->query("SELECT id FROM technologies WHERE name='Phase3 Java'")->fetchColumn();$tech2=(int)$db->query("SELECT id FROM technologies WHERE name='Phase3 Python'")->fetchColumn();
$db->exec("INSERT INTO users(role,full_name,username,password_hash) VALUES('ADMIN','Phase Admin','phase.admin','x')");$admin=(int)$db->lastInsertId();$a=p3candidate($db,$tech,'Alice Phase','+919100000001');$b=p3candidate($db,$tech2,'Bob Phase','+919100000002','Fake');$c=p3candidate($db,$tech,'Cara Phase','+919100000003');$hari=(int)$db->query("SELECT id FROM support_people WHERE name='Hari'")->fetchColumn();$arjun=(int)$db->query("SELECT id FROM support_people WHERE name='Arjun'")->fetchColumn();
[$hours,$booking]=p3services($db,'2030-01-07T06:00:00+00:00'); // 11:30 IST Monday
$inside=$booking->createAsAdmin($admin,$a,p3input($tech,'2030-01-07','12:00'));p3ok($inside>0,'admin creates inside candidate advance cutoff');p3ok((int)$db->query("SELECT COUNT(*) FROM audit_logs WHERE action='admin.cutoff_override' AND entity_id=$inside")->fetchColumn()===1,'create cutoff override audited');
p3reject(fn()=>$booking->createAsAdmin($admin,$a,p3input($tech,'2030-01-07','12:15')),'another interview');
$bOverlap=$booking->createAsAdmin($admin,$b,p3input($tech2,'2030-01-07','12:00'));p3reject(fn()=>$booking->createAsAdmin($admin,$c,p3input($tech,'2030-01-07','12:00')),'No Normal computer');
$tool=$booking->createAsAdmin($admin,$c,p3input($tech,'2030-01-07','13:00','TOOL',$hari,60));p3reject(fn()=>$booking->createAsAdmin($admin,$b,p3input($tech,'2030-01-07','13:15','TOOL',$hari)),'already assigned');p3reject(fn()=>$booking->createAsAdmin($admin,$b,p3input($tech,'2030-01-07','19:00')),'outside business hours');
$before=$db->query("SELECT start_time,resource_id FROM interviews WHERE id=$inside")->fetch();$booking->rescheduleAsAdmin($admin,$inside,p3input($tech,'2030-01-07','12:45','TOOL',$arjun,45));$moved=$db->query("SELECT start_time,interview_type,support_person_id FROM interviews WHERE id=$inside")->fetch();p3ok($moved['interview_type']==='TOOL'&&(int)$moved['support_person_id']===$arjun,'admin reschedule changes type and support');p3ok($moved['start_time']==='2030-01-07 07:15:00','admin reschedule bypasses cutoff');
p3reject(fn()=>$booking->rescheduleAsAdmin($admin,$inside,p3input($tech,'2030-01-07','13:15','TOOL',$hari,30)),'already assigned');p3ok($db->query("SELECT start_time FROM interviews WHERE id=$inside")->fetchColumn()==='2030-01-07 07:15:00','failed admin reschedule preserves original');
$booking->cancelAsAdmin($admin,$inside);p3ok($db->query("SELECT status FROM interviews WHERE id=$inside")->fetchColumn()==='CANCELLED','admin cancel inside cutoff succeeds');p3ok((int)$db->query("SELECT COUNT(*) FROM audit_logs WHERE action='admin.booking.cancelled' AND entity_id=$inside")->fetchColumn()===1,'admin cancellation audited');$released=$booking->createAsAdmin($admin,$a,p3input($tech,'2030-01-07','12:45','TOOL',$arjun,45));p3ok($released>0,'admin cancellation releases resource and support');

$repo=new AdminRepository($db);$tz=$hours->timezone();$day=$repo->calendar(new DateTimeImmutable('2030-01-07',$tz),new DateTimeImmutable('2030-01-08',$tz));p3ok(count(array_filter($day,fn($r)=>$r['status']==='CANCELLED'))===0,'day calendar excludes cancelled interviews');p3ok(count($day)>=3,'day calendar returns selected-day bookings');p3ok(isset($day[0]['candidate_name'],$day[0]['resource_name'],$day[0]['technology_name']),'calendar query joins display data');p3ok((bool)array_filter($day,fn($r)=>$r['interview_type']==='TOOL'&&$r['support_person_name']==='Hari'),'calendar shows Tool support assignment');$week=$repo->calendar(new DateTimeImmutable('2030-01-07',$tz),new DateTimeImmutable('2030-01-14',$tz));p3ok(count($week)===count($day),'week query respects bounded date range');
$dashboard=$repo->dashboard(new DateTimeImmutable('2030-01-07 12:10:00',$tz));p3ok($dashboard['current']!==null&&$dashboard['current']['candidate_name']==='Bob Phase','dashboard calculates happening now');p3ok($dashboard['next']!==null,'dashboard calculates next booking');p3ok($dashboard['metrics']['today']===count($day),'dashboard today metric matches calendar');

$ops=new AdminOperationsService($db,new AuditService($db));$resource=$ops->saveResource($admin,['id'=>'0','name'=>'Phase Spare PC','type'=>'NORMAL','active'=>'1']);p3ok($resource>0,'resource created');$ops->saveResource($admin,['id'=>(string)$resource,'name'=>'Phase Spare PC Renamed','type'=>'NORMAL','active'=>'1']);p3ok($db->query("SELECT name FROM resources WHERE id=$resource")->fetchColumn()==='Phase Spare PC Renamed','resource edited');$ops->saveResource($admin,['id'=>(string)$resource,'name'=>'Phase Spare PC Renamed','type'=>'NORMAL','active'=>'0']);p3ok((int)$db->query("SELECT active FROM resources WHERE id=$resource")->fetchColumn()===0,'unused resource deactivated');$usedResource=(int)$db->query("SELECT resource_id FROM interviews WHERE id=$bOverlap")->fetchColumn();p3reject(fn()=>$ops->saveResource($admin,['id'=>(string)$usedResource,'name'=>(string)$db->query("SELECT name FROM resources WHERE id=$usedResource")->fetchColumn(),'type'=>'NORMAL','active'=>'0']),'upcoming interview');
p3reject(fn()=>$ops->saveResource($admin,['id'=>(string)$usedResource,'name'=>(string)$db->query("SELECT name FROM resources WHERE id=$usedResource")->fetchColumn(),'type'=>'TOOL','active'=>'1']),'upcoming interview');
$person=$ops->saveSupportPerson($admin,['id'=>'0','name'=>'Phase Helper','active'=>'1']);p3ok($person>0,'support person created');$ops->saveSupportPerson($admin,['id'=>(string)$person,'name'=>'Phase Helper Renamed','active'=>'1']);p3ok($db->query("SELECT name FROM support_people WHERE id=$person")->fetchColumn()==='Phase Helper Renamed','support person edited');$ops->saveSupportPerson($admin,['id'=>(string)$person,'name'=>'Phase Helper Renamed','active'=>'0']);p3ok((int)$db->query("SELECT active FROM support_people WHERE id=$person")->fetchColumn()===0,'unused support person deactivated');p3reject(fn()=>$ops->saveSupportPerson($admin,['id'=>(string)$hari,'name'=>'Hari','active'=>'0']),'upcoming interview');

$found=$repo->candidates(['search'=>'Alice','technology_id'=>'','classification'=>''],1,20);p3ok($found['total']===1&&(int)$found['rows'][0]['id']===$a,'candidate name search');$found=$repo->candidates(['search'=>'+919100000002','technology_id'=>(string)$tech2,'classification'=>'Fake'],1,20);p3ok($found['total']===1&&(int)$found['rows'][0]['id']===$b,'candidate phone and profile filters');p3ok($repo->candidate($a)['phone']==='+919100000001','candidate detail is candidate-scoped');p3ok($repo->candidate($admin)===null,'admin cannot be resolved as candidate detail');

$ops->saveSettings($admin,p3hours());p3ok((int)$db->query("SELECT setting_value FROM app_settings WHERE setting_key='advance_booking_minutes'")->fetchColumn()===90,'minimum notice updated');p3ok((int)$db->query("SELECT setting_value FROM app_settings WHERE setting_key='candidate_change_cutoff_minutes'")->fetchColumn()===75,'candidate cutoff updated');p3reject(fn()=>$ops->saveSettings($admin,p3hours(['opens'=>[1=>'19:00'],'closes'=>[1=>'10:00']])),'valid opening');p3reject(fn()=>$ops->saveSettings($admin,p3hours(['closes'=>[1=>'12:15']])),'invalidate');p3ok((int)$db->query("SELECT COUNT(*) FROM audit_logs WHERE action='settings.scheduling.updated'")->fetchColumn()>=1,'settings change audited');
p3reject(fn()=>$ops->saveSettings($admin,['advance_minutes'=>'60','cutoff_minutes'=>'60','open'=>'invalid','opens'=>'invalid','closes'=>'invalid']),'valid opening');

$interviews=new InterviewRepository($db);$page=$interviews->adminPaginated(['search'=>'Phase','date_from'=>'2030-01-07','date_to'=>'2030-01-07','resource_id'=>(string)$usedResource],$tz,1,1);p3ok(count($page['rows'])===1&&$page['total']>=1,'interview search, date range, resource filter, and pagination');p3ok((int)$db->query("SELECT COUNT(*) FROM audit_logs WHERE action IN ('resource.created','resource.updated','support_person.created','support_person.updated')")->fetchColumn()>=6,'directory mutations audited');
echo $checks." Phase 3 checks passed.\n";
